CREATE TRIGGER xlog_qso_read_delete AFTER DELETE ON qsos BEGIN
    DELETE FROM xlog_qso_read_projection WHERE local_id = OLD.local_id;
END

CREATE TRIGGER xlog_qso_read_insert AFTER INSERT ON qsos BEGIN
    INSERT OR REPLACE INTO xlog_qso_read_projection(local_id,qso_start,band,mode,deleted_at,dxcc_int,json_dxcc,json_cq_zone,json_state,json_grid,json_submode,json_qsl,json_lotw,json_continent,json_pota,json_sota,json_iota,json_wwff,json_sig,json_sig_info,json_band,json_mode,json_call,json_start) SELECT NEW.local_id,NEW.qso_start,NEW.band,NEW.mode,NEW.deleted_at,CAST(json_extract(NEW.record_json,'$.dxcc') AS INTEGER),json_extract(NEW.record_json,'$.dxcc'),json_extract(NEW.record_json,'$.cqZone'),json_extract(NEW.record_json,'$.state'),json_extract(NEW.record_json,'$.gridSquare'),json_extract(NEW.record_json,'$.submode'),json_extract(NEW.record_json,'$.qslReceived'),json_extract(NEW.record_json,'$.lotwReceived'),json_extract(NEW.record_json,'$.continent'),json_extract(NEW.record_json,'$.potaReference'),json_extract(NEW.record_json,'$.sotaReference'),json_extract(NEW.record_json,'$.iota'),json_extract(NEW.record_json,'$.wwffReference'),json_extract(NEW.record_json,'$.sig'),json_extract(NEW.record_json,'$.sigInfo'),json_extract(NEW.record_json,'$.band'),json_extract(NEW.record_json,'$.mode'),json_extract(NEW.record_json,'$.call'),json_extract(NEW.record_json,'$.start');
END

CREATE TRIGGER xlog_qso_read_update AFTER UPDATE OF local_id,qso_start,band,mode,deleted_at,record_json ON qsos BEGIN
    DELETE FROM xlog_qso_read_projection WHERE local_id = OLD.local_id;
    INSERT OR REPLACE INTO xlog_qso_read_projection(local_id,qso_start,band,mode,deleted_at,dxcc_int,json_dxcc,json_cq_zone,json_state,json_grid,json_submode,json_qsl,json_lotw,json_continent,json_pota,json_sota,json_iota,json_wwff,json_sig,json_sig_info,json_band,json_mode,json_call,json_start) SELECT NEW.local_id,NEW.qso_start,NEW.band,NEW.mode,NEW.deleted_at,CAST(json_extract(NEW.record_json,'$.dxcc') AS INTEGER),json_extract(NEW.record_json,'$.dxcc'),json_extract(NEW.record_json,'$.cqZone'),json_extract(NEW.record_json,'$.state'),json_extract(NEW.record_json,'$.gridSquare'),json_extract(NEW.record_json,'$.submode'),json_extract(NEW.record_json,'$.qslReceived'),json_extract(NEW.record_json,'$.lotwReceived'),json_extract(NEW.record_json,'$.continent'),json_extract(NEW.record_json,'$.potaReference'),json_extract(NEW.record_json,'$.sotaReference'),json_extract(NEW.record_json,'$.iota'),json_extract(NEW.record_json,'$.wwffReference'),json_extract(NEW.record_json,'$.sig'),json_extract(NEW.record_json,'$.sigInfo'),json_extract(NEW.record_json,'$.band'),json_extract(NEW.record_json,'$.mode'),json_extract(NEW.record_json,'$.call'),json_extract(NEW.record_json,'$.start');
END

